// Uses only the installed Playwright package. No downloads or server are needed.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const crypto = require('node:crypto');
const { chromium } = require('playwright');

(async () => {
  const sourcePath = path.resolve(__dirname, '..', 'index.html');
  const report = {
    artifact: 'index.html',
    sha256: crypto.createHash('sha256').update(fs.readFileSync(sourcePath)).digest('hex'),
    browser: 'Playwright Chromium',
    executablePath: chromium.executablePath(),
    completedChecks: []
  };
  let browser;
  try {
    browser = await chromium.launch({ headless: true });
  } catch (error) {
    report.status = 'BLOCKED';
    report.blocker = error.message;
    report.unverified = ['Keyboard operation', 'Browser behavior', 'Computed accessible names', 'Rendered appearance', 'Final screenshot'];
    fs.writeFileSync(path.join(__dirname, 'browser-check.json'), JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify(report, null, 2));
    process.exitCode = 2;
    return;
  }
  try {
    const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    await page.goto(pathToFileURL(sourcePath).href);
    const filter = page.getByRole('textbox', { name: 'Filter', exact: true });
    const checkbox = name => page.getByRole('checkbox', { name, exact: true });
    const exportButton = page.getByRole('button', { name: 'Export selected', exact: true });
    const focused = locator => locator.evaluate(element => element === document.activeElement);
    assert.equal(await exportButton.isDisabled(), true);
    assert.equal(await page.getByRole('checkbox').count(), 3);
    report.completedChecks.push('Named row checkboxes and initially disabled export');

    await page.keyboard.press('Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(checkbox('Amber')), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(checkbox('Birch')), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(checkbox('Cedar')), true);
    await page.keyboard.press('Space');
    assert.equal(await checkbox('Cedar').isChecked(), true);
    assert.equal(await focused(checkbox('Cedar')), true);
    report.completedChecks.push('Tab reaches filter and each checkbox; Space selects Cedar without losing focus');

    for (let index = 0; index < 3; index++) await page.keyboard.press('Shift+Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.type('Birch');
    assert.equal(await page.getByRole('checkbox').count(), 1);
    assert.equal(await page.locator('#count').textContent(), '1 selected (1 hidden by filter)');
    await page.keyboard.press('Tab');
    assert.equal(await focused(checkbox('Birch')), true);
    await page.keyboard.press('Space');
    assert.equal(await focused(checkbox('Birch')), true);
    assert.equal(await page.locator('#count').textContent(), '2 selected (1 hidden by filter)');
    await page.keyboard.press('Tab');
    assert.equal(await focused(exportButton), true);
    await page.keyboard.press('Enter');
    assert.equal(await page.locator('#result').textContent(), 'r2,r3');
    report.completedChecks.push('Keyboard filtering, hidden selection and Enter export yield r2,r3 in dataset order');

    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Shift+Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.press('ControlOrMeta+A');
    await page.keyboard.type('no-match');
    assert.equal(await page.getByRole('checkbox').count(), 0);
    assert.equal(await page.locator('#empty').isVisible(), true);
    assert.equal(await page.locator('#count').textContent(), '2 selected (2 hidden by filter)');
    await page.keyboard.press('Tab');
    assert.equal(await focused(exportButton), true);
    await page.keyboard.press('Space');
    assert.equal(await page.locator('#result').textContent(), 'r2,r3');
    report.completedChecks.push('Zero-match state keeps hidden selections and supports keyboard export');

    await page.keyboard.press('Shift+Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.press('ControlOrMeta+A');
    await page.keyboard.press('Backspace');
    assert.equal(await checkbox('Birch').isChecked(), true);
    assert.equal(await checkbox('Cedar').isChecked(), true);
    assert.equal(await checkbox('Amber').isChecked(), false);
    assert.equal(await page.locator('#empty').isVisible(), false);
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');
    assert.equal(await focused(checkbox('Birch')), true);
    await page.keyboard.press('Space');
    await page.keyboard.press('Tab');
    assert.equal(await focused(checkbox('Cedar')), true);
    await page.keyboard.press('Space');
    assert.equal(await exportButton.isDisabled(), true);
    assert.equal(await focused(checkbox('Cedar')), true);
    report.completedChecks.push('Clearing filter restores selections; keyboard deselection disables export');

    // Finish with a useful hidden-selection/export state for the single capture.
    await page.keyboard.press('Space');
    for (let index = 0; index < 3; index++) await page.keyboard.press('Shift+Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.type('Birch');
    await page.keyboard.press('Tab');
    await page.keyboard.press('Space');
    await page.keyboard.press('Tab');
    await page.keyboard.press('Enter');
    assert.equal(await page.locator('#result').textContent(), 'r2,r3');
    assert.deepEqual(errors, []);
    const screenshot = path.join(__dirname, 'final.png');
    await page.screenshot({ path: screenshot, fullPage: true });
    report.status = 'PASS';
    report.screenshot = 'evidence/final.png';
    report.unverified = ['Manual visual review', 'Assistive technology announcements'];
  } catch (error) {
    report.status = 'FAIL';
    report.failure = error.stack;
    process.exitCode = 1;
  } finally {
    await browser.close();
    fs.writeFileSync(path.join(__dirname, 'browser-check.json'), JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify(report, null, 2));
  }
})().catch(error => {
  console.error(error.stack);
  process.exitCode = 1;
});

