// This uses the installed Playwright package and never installs a browser.
const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { chromium } = require('playwright');

(async () => {
  let browser;
  try {
    browser = await chromium.launch({ headless: true });
  } catch (error) {
    console.error('BLOCKED: Playwright could not launch Chromium. No UI assertions or screenshot ran.');
    console.error(error.message);
    process.exitCode = 2;
    return;
  }
  try {
    const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
    await page.goto(pathToFileURL(path.join(__dirname, '..', 'index.html')).href);
    const filter = page.getByRole('textbox', { name: 'Filter', exact: true });
    const amber = page.getByRole('checkbox', { name: 'Amber', exact: true });
    const birch = page.getByRole('checkbox', { name: 'Birch', exact: true });
