    assert.equal(await page.locator('#count').textContent(), '0 selected');
    assert.equal(await amber.count(), 1);
    assert.equal(await birch.count(), 1);
    assert.equal(await cedar.count(), 1);

    await page.keyboard.press('Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(amber), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(birch), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(cedar), true);
    await page.keyboard.press('Space');
    assert.equal(await cedar.isChecked(), true);
    assert.equal(await focused(cedar), true);
    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Space');
    assert.equal(await amber.isChecked(), true);
    assert.equal(await focused(amber), true);

    await page.keyboard.press('Shift+Tab');
    assert.equal(await focused(filter), true);
    await page.keyboard.type('Birch');
    assert.equal(await page.getByRole('checkbox').count(), 1);
    assert.equal(await page.locator('#count').textContent(), '2 selected');
    assert.equal(await exportButton.isDisabled(), false);
    await page.keyboard.press('Tab');
    assert.equal(await focused(birch), true);
    await page.keyboard.press('Tab');
    assert.equal(await focused(exportButton), true);
    await page.keyboard.press('Enter');
    assert.equal(await page.locator('#result').textContent(), 'r1,r3');

    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Control+A');
    await page.keyboard.type('NoMatch');
    assert.equal(await page.getByRole('checkbox').count(), 0);
    assert.equal(await page.locator('#empty').isVisible(), true);
    assert.equal(await page.locator('#count').textContent(), '2 selected');
    await page.keyboard.press('Tab');
    assert.equal(await focused(exportButton), true);
    await page.keyboard.press('Space');
    assert.equal(await page.locator('#result').textContent(), 'r1,r3');

    await page.keyboard.press('Shift+Tab');
    await page.keyboard.press('Control+A');
    await page.keyboard.press('Backspace');
    assert.equal(await amber.isChecked(), true);
    assert.equal(await cedar.isChecked(), true);
    assert.equal(await page.locator('#empty').isVisible(), false);
    await page.keyboard.press('Tab');
    await page.keyboard.press('Space');
    assert.equal(await page.locator('#count').textContent(), '1 selected');
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');
    await page.keyboard.press('Space');
    assert.equal(await page.locator('#count').textContent(), '0 selected');
    assert.equal(await exportButton.isDisabled(), true);
    await page.screenshot({ path: path.join(__dirname, 'final.png'), fullPage: true });
    console.log('PASS: keyboard filter, named checkboxes, focus retention, hidden selection, ordered export, no matches, restoration, empty-selection disablement.');
    console.log('Screenshot: evidence/final.png');
  } finally {
    await browser.close();
  }
})().catch(error => {
  console.error(error.stack);
  process.exitCode = 1;
});

