"""Coordinator-only retention of completed assignments; never launches subjects."""
import argparse
import datetime
import hashlib
import json
from pathlib import Path
import shutil

ROOT = Path('/workspace/scratch/396f0b68d07d')
RUNTIME = ROOT / 'comparison-runtime'
CAPTURE = ROOT / 'comparison-capture'
PLAN = {r['run_id']: r for r in json.loads((RUNTIME/'runtime-plan.json').read_text())}
IGNORE = {'.git', '__pycache__', '.pytest_cache'}

def sha(data):
    return hashlib.sha256(data).hexdigest()

def inventory(root):
    result={}
    for p in sorted(root.rglob('*')):
        relative=p.relative_to(root)
        if any(part in IGNORE for part in relative.parts): continue
        if p.is_symlink(): raise ValueError(f'Unreviewed link: {p}')
        if p.is_file(): result[relative.as_posix()]=sha(p.read_bytes())
    return result

def capture(run_id):
    row=PLAN[run_id]
    home=CAPTURE/run_id
    if home.exists():
        saved=json.loads((home/'capture.json').read_text())
        if inventory(home/'work') != saved['output_files']:
            raise ValueError('Retained evidence changed: '+run_id)
        return {'run_id':run_id,'capture':'already retained','files':len(saved['output_files'])}
    packet=Path(row['packet'])
    observed={k:v for k,v in inventory(packet).items() if k != 'manifest.json'}
    if observed != row['packet_files']: raise ValueError('Packet files drifted: '+run_id)
    if sha((packet/'manifest.json').read_bytes()) != row['packet_manifest_sha256']:
        raise ValueError('Manifest drifted: '+run_id)
    if sha(Path(row['launch_file']).read_bytes()) != row['launch_sha256']:
        raise ValueError('Launch drifted: '+run_id)
    work=Path(row['work'])
    before=inventory(work)
    if 'answer.md' not in before: raise ValueError('No requested answer: '+run_id)
    home.mkdir(parents=True)
    shutil.copytree(work,home/'work',ignore=shutil.ignore_patterns(*IGNORE))
    shutil.copy2(row['launch_file'],home/'launch.txt')
    shutil.copy2(packet/'manifest.json',home/'packet-manifest.json')
    after=inventory(home/'work')
    if before != after: raise ValueError('Capture mismatch: '+run_id)
    source={k.removeprefix('inputs/'):v for k,v in row['packet_files'].items() if k.startswith('inputs/')}
    record={'run_id':run_id,'capture_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
            'packet_integrity':'all retained packet files and manifest match preparation',
            'output_files':after,'source_files':source,
            'changed_source_files':[k for k,v in source.items() if after.get(k)!=v],
            'new_files':[k for k in after if k not in source],
            'excluded_transient_components':sorted(IGNORE),
            'trace_limit':'Final retained bytes and worker reports; no exported host trajectory or proof of no transient writes/outside reads.'}
    (home/'capture.json').write_text(json.dumps(record,indent=2)+'\n')
    return {'run_id':run_id,'capture':'retained','files':len(after),'changed_source_files':record['changed_source_files']}

if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('runs',nargs='+')
    args=parser.parse_args()
    for run_id in args.runs: print(json.dumps(capture(run_id)))

