const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

// This small DOM substitute executes the supplied script and its event handlers.
// It does not render, implement browser focus, or compute accessibility names.
class Element {
  constructor(tagName, text = '') {
    this.tagName = tagName.toUpperCase();
    this.childNodes = [];
    this.parentElement = null;
    this.listeners = {};
    this.value = '';
    this.checked = false;
    this.disabled = false;
    this.hidden = false;
    this.text = text;
  }
  append(...nodes) {
    for (const node of nodes) {
      node.parentElement = this;
      this.childNodes.push(node);
    }
  }
  replaceChildren(...nodes) {
    for (const node of this.childNodes) node.parentElement = null;
    this.childNodes = [];
    this.append(...nodes);
  }
  addEventListener(type, handler) { (this.listeners[type] ??= []).push(handler); }
  dispatch(type) { for (const handler of this.listeners[type] ?? []) handler({ target: this }); }
  get textContent() { return this.text + this.childNodes.map(node => node.textContent).join(''); }
  set textContent(value) { this.text = String(value); this.replaceChildren(); }
}

function load(filename) {
  const html = fs.readFileSync(filename, 'utf8');
  const elements = {};
  for (const match of html.matchAll(/<([a-z][\w-]*)\b[^>]*\bid=["']([^"']+)["'][^>]*>/gi)) {
    const element = elements[match[2]] = new Element(match[1]);
    element.disabled = /\sdisabled(?:\s|>|=)/.test(match[0]);
    element.hidden = /\shidden(?:\s|>|=)/.test(match[0]);
  }
  const document = {
    querySelector: selector => elements[selector.slice(1)] ?? null,
    createElement: tagName => new Element(tagName),
    createTextNode: text => new Element('#text', text)
  };
  vm.runInNewContext(html.match(/<script>([\s\S]*?)<\/script>/)[1], { document }, { filename });
  function descendants(element) {
    return element.childNodes.flatMap(node => [node, ...descendants(node)]);
  }
  const checkboxes = () => descendants(elements.rows).filter(node => node.type === 'checkbox');
  const rowName = checkbox => {
    let row = checkbox;
    while (row.tagName !== 'LI') row = row.parentElement;
    return row.textContent.trim();
  };
  const checkbox = name => checkboxes().find(node => rowName(node) === name);
  const toggle = (name, checked) => {
    const node = checkbox(name);
    assert.ok(node, 'Expected visible checkbox for ' + name);
    node.checked = checked;
    node.dispatch('change');
    return node;
  };
  const filter = value => { elements.filter.value = value; elements.filter.dispatch('input'); };
  const exportSelected = () => {
    if (!elements.export.disabled) elements.export.dispatch('click');
    return elements.result.textContent;
  };
  return { elements, checkboxes, checkbox, rowName, toggle, filter, exportSelected };
}

function inspect(filename) {
  const app = load(filename);
  const checks = {};
  checks['Empty selection disables export initially'] = app.elements.export.disabled;
  checks['Every checkbox has a wrapping label that names its row'] = app.checkboxes().every(node =>
    node.parentElement.tagName === 'LABEL' && node.parentElement.textContent.trim() === app.rowName(node));
  const cedar = app.toggle('Cedar', true);
  checks['Checkbox change preserves the checkbox node'] = app.checkbox('Cedar') === cedar;
  app.filter('AM');
  checks['Filter is case insensitive and shows only Amber'] = app.checkboxes().length === 1 && !!app.checkbox('Amber');
  checks['Hidden Cedar remains counted and can be exported'] =
    /^1 selected\b/.test(app.elements.count.textContent) && app.exportSelected() === 'r3';
  app.toggle('Amber', true);
  checks['Count includes both selected records with Cedar hidden'] = /^2 selected\b/.test(app.elements.count.textContent);
  checks['Reverse selection order exports dataset order including hidden Cedar'] = app.exportSelected() === 'r1,r3';
  app.filter('no-match');
  checks['No-match filter shows an empty state'] =
    app.checkboxes().length === 0 && app.elements.empty?.hidden === false;
  checks['All-hidden selection remains counted and exportable'] =
    /^2 selected\b/.test(app.elements.count.textContent) && !app.elements.export.disabled && app.exportSelected() === 'r1,r3';
  app.filter('');
  checks['Clearing filter restores selected checkboxes'] =
    app.checkbox('Amber').checked && !app.checkbox('Birch').checked && app.checkbox('Cedar').checked;
  checks['Clearing filter hides the empty state'] = app.elements.empty?.hidden === true;
  app.toggle('Cedar', false);
  checks['Deselecting Cedar leaves only Amber in export'] = app.exportSelected() === 'r1';
  app.toggle('Amber', false);
  checks['Deselecting the final record disables export'] = app.elements.export.disabled && app.elements.count.textContent === '0 selected';
  app.filter('no-match');
  checks['Empty filter result with no selection keeps export disabled'] =
    app.elements.export.disabled && app.elements.empty?.hidden === false;
  return checks;
}

const root = path.resolve(__dirname, '..');
const before = inspect(path.join(__dirname, 'index.before.html'));
const after = inspect(path.join(root, 'index.html'));
console.log('Executed JavaScript event checks in a simulated DOM; no rendering or keyboard execution.');
for (const [description, passed] of Object.entries(after)) {
  console.log(`${passed ? 'PASS' : 'FAIL'} | before=${before[description] ? 'pass' : 'fail'} | ${description}`);
}
assert.ok(Object.values(after).every(Boolean), 'The repaired script must satisfy every behavioral check');
console.log(`After repair: ${Object.keys(after).length}/${Object.keys(after).length} simulated DOM checks passed.`);

