// Executes the actual inline script using a small DOM stand-in.
// These are logic/structure checks, not browser, keyboard or accessibility checks.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

class Element {
  constructor(tagName) {
    this.tagName = tagName;
    this.children = [];
    this.listeners = new Map();
    this.value = '';
    this.textContent = '';
    this.checked = false;
    this.disabled = false;
    this.hidden = false;
  }
  append(...children) { this.children.push(...children); }
  replaceChildren(...children) { this.children = children; }
  addEventListener(type, callback) { this.listeners.set(type, callback); }
  dispatch(type) { this.listeners.get(type)?.(); }
}

const filename = process.argv[2] || path.join(__dirname, '..', 'index.html');
const html = fs.readFileSync(filename, 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
const elements = Object.fromEntries(['filter', 'rows', 'count', 'export', 'result', 'empty']
  .map(id => [id, new Element(id)]));
const document = {
  querySelector: selector => elements[selector.slice(1)],
  createElement: tagName => new Element(tagName),
  createTextNode: text => ({ textContent: text })
};
vm.runInNewContext(script, { document }, { filename });

function row(name) {
  for (const li of elements.rows.children) {
    const label = li.children.find(child => child.tagName === 'label');
    if (label?.children.some(child => child.textContent?.trim() === name)) {
      return label.children.find(child => child.tagName === 'input');
    }
    // Permit testing the old unlabeled structure for the baseline regression.
    if (li.children.some(child => child.textContent?.trim() === name)) {
      return li.children.find(child => child.tagName === 'input');
    }
  }
}
function select(name, checked) {
  const checkbox = row(name);
  assert.ok(checkbox, 'Row must exist: ' + name);
  checkbox.checked = checked;
  checkbox.dispatch('change');
  return checkbox;
}
function filter(value) {
  elements.filter.value = value;
  elements.filter.dispatch('input');
}
const results = [];
function check(name, callback) {
  try { callback(); results.push({ name, status: 'PASS' }); }
  catch (error) { results.push({ name, status: 'FAIL', detail: error.message }); }
}

check('Initial count and disabled export', () => {
  assert.equal(elements.count.textContent, '0 selected');
  assert.equal(elements.export.disabled, true);
});
select('Cedar', true);
const amber = select('Amber', true);
check('Checkbox node survives selection changes (structure only)', () => {
  assert.equal(row('Amber'), amber);
});
filter('bIrCh');
check('Filter matches case-insensitively and keeps all selected IDs in count', () => {
  assert.equal(elements.rows.children.length, 1);
  assert.ok(row('Birch'));
  assert.equal(elements.count.textContent, '2 selected');
  assert.equal(elements.export.disabled, false);
});
elements.export.dispatch('click');
check('Export includes hidden selections in dataset order, independent of selection order', () => {
  assert.equal(elements.result.textContent, 'r1,r3');
});
filter('NoMatch');
check('No-match state preserves selection and offers visible recovery text', () => {
  assert.equal(elements.rows.children.length, 0);
  assert.equal(elements.empty.hidden, false);
  assert.equal(elements.count.textContent, '2 selected');
  assert.equal(elements.export.disabled, false);
  assert.match(html, /No matching records\. Change or clear the filter/);
});
elements.export.dispatch('click');
check('Export works when every selected row is hidden and no rows match', () => {
  assert.equal(elements.result.textContent, 'r1,r3');
});
filter('');
check('Clearing filter restores checked rows and hides no-match message', () => {
  assert.equal(elements.rows.children.length, 3);
  assert.equal(row('Amber').checked, true);
  assert.equal(row('Cedar').checked, true);
  assert.equal(row('Birch').checked, false);
  assert.equal(elements.empty.hidden, true);
});
check('Each checkbox is nested in a label with its row name (structure only)', () => {
  for (const name of ['Amber', 'Birch', 'Cedar']) {
    assert.ok(elements.rows.children.some(li => {
      const label = li.children.find(child => child.tagName === 'label');
      return label?.children.includes(row(name)) &&
        label.children.some(child => child.textContent?.trim() === name);
    }), 'Missing associated row label: ' + name);
  }
});
select('Amber', false);
check('Deselecting a restored record updates total and subsequent export', () => {
  assert.equal(elements.count.textContent, '1 selected');
  elements.export.dispatch('click');
  assert.equal(elements.result.textContent, 'r3');
});
select('Cedar', false);
check('Removing the last selection disables export', () => {
  assert.equal(elements.count.textContent, '0 selected');
  assert.equal(elements.export.disabled, true);
});
console.log(JSON.stringify({ source: filename, method: 'Node VM with DOM stand-in; no browser or keyboard execution', results }, null, 2));
process.exitCode = results.some(result => result.status === 'FAIL') ? 1 : 0;

