// Real keyboard journey. Requires an already-installed Playwright Chromium.
// No package or browser downloads are performed by this script.
const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { chromium } = require('playwright');

(async () => {
  let browser;
  try {
    browser = await chromium.launch({ headless: true });
    const page = await browser.newPage({ viewport: { width: 1000, height: 800 } });
    await page.goto(pathToFileURL(path.resolve(__dirname, '../index.html')).href);
    const focused = async locator => assert.equal(await locator.evaluate(node => node === document.activeElement), true);
    const press = key => page.keyboard.press(key);
    const filter = page.getByRole('textbox', { name: 'Filter', exact: true });
    const amber = page.getByRole('checkbox', { name: 'Amber', exact: true });
    const birch = page.getByRole('checkbox', { name: 'Birch', exact: true });
    const cedar = page.getByRole('checkbox', { name: 'Cedar', exact: true });
    const exportButton = page.getByRole('button', { name: 'Export selected', exact: true });

    assert.equal(await exportButton.isDisabled(), true);
    await press('Tab');
    await focused(filter);
    await press('Tab');
    await focused(amber);
    await press('Tab');
    await focused(birch);
    await press('Tab');
    await focused(cedar);
    await press('Space');
    await focused(cedar);
    assert.equal(await cedar.isChecked(), true);
    await press('Shift+Tab');
    await press('Shift+Tab');
    await press('Shift+Tab');
    await focused(filter);
    await page.keyboard.type('am');
    assert.equal(await page.getByRole('checkbox').count(), 1);
    assert.equal(await page.locator('#count').textContent(), '1 selected');
    await press('Tab');
    await focused(amber);
    await press('Space');
    await focused(amber);
    await press('Tab');
    await focused(exportButton);
    await press('Enter');
    assert.equal(await page.locator('#result').textContent(), 'r1,r3');

    await press('Shift+Tab');
    await press('Shift+Tab');
    await focused(filter);
    await press('ControlOrMeta+A');
    await page.keyboard.type('no-match');
    assert.equal(await page.getByRole('checkbox').count(), 0);
    assert.equal(await page.locator('#empty').isVisible(), true);
    assert.equal(await page.locator('#count').textContent(), '2 selected');
    await press('Tab');
    await focused(exportButton);
    await press('Space');
    assert.equal(await page.locator('#result').textContent(), 'r1,r3');
    await press('Shift+Tab');
    await focused(filter);
    await press('ControlOrMeta+A');
    await press('Backspace');
    assert.equal(await amber.isChecked(), true);
    assert.equal(await cedar.isChecked(), true);
    await press('Tab');
    await press('Space');
    await focused(amber);
    await press('Tab');
    await press('Tab');
    await focused(cedar);
    await press('Space');
    await focused(cedar);
    assert.equal(await exportButton.isDisabled(), true);

    // Finish with a useful hidden-selection state and an executed export.
    await press('Space');
    await press('Shift+Tab');
    await press('Shift+Tab');
    await press('Shift+Tab');
    await focused(filter);
    await page.keyboard.type('am');
    await press('Tab');
    await press('Space');
    await press('Tab');
    await focused(exportButton);
    await press('Enter');
    assert.equal(await page.locator('#result').textContent(), 'r1,r3');
    await page.screenshot({ path: path.resolve(__dirname, 'final.png'), fullPage: true });
    console.log('PASS: keyboard navigation, selection, hidden-selection export, empty-filter recovery, and disabled export.');
    console.log('Saved final.png: Amber visible and selected, Cedar hidden and selected, result r1,r3; viewport 1000 x 800.');
  } catch (error) {
    console.error(browser ? 'FAIL: browser journey' : 'BLOCKED: browser did not launch');
    console.error(error.message);
    process.exitCode = 1;
  } finally {
    if (browser) await browser.close();
  }
})();

