// Executes the application's actual inline script against a minimal DOM stub.
// This checks event-handler state and constructed nodes, not browser behavior,
// computed accessible names, focus, keyboard input, layout, or announcements.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');

class Element {
  constructor(tagName, text = '') {
    this.tagName = tagName.toUpperCase();
    this.children = [];
    this.parentNode = null;
    this.listeners = new Map();
    this.value = '';
    this.checked = false;
    this.disabled = false;
    this.hidden = false;
    this._text = text;
  }
  append(...nodes) {
    for (const node of nodes) {
      node.parentNode = this;
      this.children.push(node);
    }
  }
  replaceChildren(...nodes) {
    for (const node of this.children) node.parentNode = null;
    this.children = [];
    this._text = '';
    this.append(...nodes);
  }
  get textContent() {
    return this._text + this.children.map(node => node.textContent).join('');
  }
  set textContent(text) {
    this.replaceChildren();
    this._text = String(text);
  }
  addEventListener(type, callback) {
    if (!this.listeners.has(type)) this.listeners.set(type, []);
    this.listeners.get(type).push(callback);
  }
  emit(type) {
    for (const callback of this.listeners.get(type) || []) callback({ type, target: this });
  }
}

function load(file) {
  const html = fs.readFileSync(file, 'utf8');
  const elements = new Map();
  for (const match of html.matchAll(/<(\w+)\b([^>]*)>/g)) {
    const id = match[2].match(/\bid="([^"]+)"/);
    if (!id) continue;
    const element = new Element(match[1]);
    element.disabled = /\bdisabled\b/.test(match[2]);
    element.hidden = /\bhidden\b/.test(match[2]);
    elements.set('#' + id[1], element);
  }
  const document = {
    querySelector: selector => elements.get(selector) || null,
    createElement: name => new Element(name),
    createTextNode: text => new Element('#text', text)
  };
  const source = html.match(/<script>([\s\S]*?)<\/script>/)[1];
  const context = vm.createContext({ document });
  new vm.Script(source, { filename: file }).runInContext(context);
  const get = id => elements.get('#' + id);
  const all = node => [node, ...node.children.flatMap(all)];
  const row = name => get('rows').children.find(item => item.textContent === name);
  const checkbox = name => all(row(name)).find(item => item.type === 'checkbox');
  const choose = (name, checked) => {
    const element = checkbox(name);
    element.checked = checked;
    element.emit('change');
    return element;
  };
  const filterBy = text => {
    get('filter').value = text;
    get('filter').emit('input');
  };
  const selectedIds = () => JSON.parse(vm.runInContext('JSON.stringify([...selected])', context));
  return { html, get, row, checkbox, choose, filterBy, selectedIds };
}

const root = path.resolve(__dirname, '..');
const before = load(path.join(__dirname, 'index.before.html'));
const baseline = { initialExportDisabled: before.get('export').disabled };
const oldCheckbox = before.choose('Cedar', true);
baseline.checkboxReplacedOnSelection = before.checkbox('Cedar') !== oldCheckbox;
baseline.rowHasWrappingLabel = before.checkbox('Cedar').parentNode.tagName === 'LABEL';
before.filterBy('Birch');
baseline.afterHidingCedar = { selectedIds: before.selectedIds(), count: before.get('count').textContent };
before.choose('Birch', true);
before.get('export').emit('click');
baseline.exportAfterChoosingCedarThenFilteringToBirchAndChoosingBirch = before.get('result').textContent;
before.filterBy('no-match');
baseline.emptyRows = before.get('rows').children.length;
baseline.emptyMessageElementPresent = Boolean(before.get('empty'));

const app = load(path.join(root, 'index.html'));
const passed = [];
function check(name, callback) {
  callback();
  passed.push(name);
}
check('Initial order, zero total and disabled export', () => {
  assert.deepEqual(app.get('rows').children.map(row => row.textContent), ['Amber', 'Birch', 'Cedar']);
  assert.match(app.get('count').textContent, /^0 selected\b/);
  assert.equal(app.get('export').disabled, true);
  assert.equal(app.get('empty').hidden, true);
});
check('Each checkbox is constructed inside a label containing its row name', () => {
  for (const name of ['Amber', 'Birch', 'Cedar']) {
    assert.equal(app.checkbox(name).parentNode.tagName, 'LABEL');
    assert.equal(app.checkbox(name).parentNode.textContent, name);
  }
});
check('Selection preserves checkbox node identity and enables export', () => {
  const checkbox = app.choose('Cedar', true);
  assert.equal(app.checkbox('Cedar'), checkbox);
  assert.equal(app.get('export').disabled, false);
  assert.deepEqual(app.selectedIds(), ['r3']);
});
check('Filtering hides Cedar without removing its selection; count includes hidden record', () => {
  app.filterBy('BiRcH');
  assert.deepEqual(app.get('rows').children.map(row => row.textContent), ['Birch']);
