// Executes the delivered inline script with a small DOM stand-in.
// This checks handler effects, not browser rendering, focus, or keyboard operation.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.resolve(__dirname, '..');
const sourcePath = path.resolve(root, process.argv[2] || 'index.html');
const html = fs.readFileSync(sourcePath, 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];

class Element {
  constructor(tag) {
    this.tagName = tag;
    this.children = [];
    this.listeners = {};
    this.value = '';
    this.checked = false;
    this.disabled = false;
    this.hidden = false;
    this.ownText = '';
  }
  append(...nodes) { this.children.push(...nodes); }
  replaceChildren(...nodes) { this.children = nodes; }
  addEventListener(type, listener) { this.listeners[type] = listener; }
  dispatch(type) { this.listeners[type]?.({ target: this }); }
  set textContent(value) { this.ownText = value; this.children = []; }
  get textContent() { return this.ownText + this.children.map(node => node.textContent).join(''); }
}

const elements = new Map();
for (const match of html.matchAll(/<([a-z]+)\b([^>]*\bid="([^"]+)"[^>]*)>/g)) {
  const element = new Element(match[1]);
  element.disabled = /\bdisabled\b/.test(match[2]);
  element.hidden = /\bhidden\b/.test(match[2]);
  elements.set('#' + match[3], element);
}
const document = {
  querySelector: selector => elements.get(selector),
  createElement: tag => new Element(tag),
  createTextNode: text => ({ textContent: text })
};
vm.runInNewContext(script, { document }, { filename: sourcePath });
const get = id => document.querySelector('#' + id);
const rowNames = () => get('rows').children.map(row => row.textContent);
const findCheckbox = node => node.type === 'checkbox' ? node : node.children?.map(findCheckbox).find(Boolean);
const checkbox = name => findCheckbox(get('rows').children.find(row => row.textContent === name));
const select = (name, checked) => {
  const control = checkbox(name);
  assert.ok(control, 'Visible checkbox for ' + name);
  control.checked = checked;
  control.dispatch('change');
};
const filter = value => {
  get('filter').value = value;
  get('filter').dispatch('input');
};
const exportSelection = () => get('export').dispatch('click');

assert.deepEqual(rowNames(), ['Amber', 'Birch', 'Cedar']);
assert.equal(get('count').textContent, '0 selected');
console.log('PASS: initial fixture and zero count');

// Start with the last dataset item to distinguish dataset order from click order.
const cedar = checkbox('Cedar');
select('Cedar', true);
filter('AM');
assert.deepEqual(rowNames(), ['Amber']);
assert.equal(get('count').textContent, '1 selected', 'Filtering must retain the hidden selection in the count');
exportSelection();
assert.equal(get('result').textContent, 'r3', 'Export must include a selected row hidden by the filter');
console.log('PASS: case-insensitive filter retains and exports hidden Cedar');

const amber = checkbox('Amber');
select('Amber', true);
assert.equal(checkbox('Amber'), amber, 'A selection change must retain the checkbox DOM node');
assert.equal(get('count').textContent, '2 selected');
assert.equal(get('export').disabled, false);
exportSelection();
assert.equal(get('result').textContent, 'r1,r3');
console.log('PASS: global count and dataset-order export after reverse-order selection');
console.log('PASS: checkbox node identity retained after selection (not a keyboard check)');

filter('no-match');
assert.deepEqual(rowNames(), []);
assert.equal(get('empty').hidden, false);
assert.equal(get('count').textContent, '2 selected');
assert.equal(get('export').disabled, false);
exportSelection();
assert.equal(get('result').textContent, 'r1,r3');
console.log('PASS: empty-filter state still exports all hidden selections');

filter('');
assert.deepEqual(rowNames(), ['Amber', 'Birch', 'Cedar']);
assert.equal(checkbox('Amber').checked, true);
assert.equal(checkbox('Birch').checked, false);
assert.equal(checkbox('Cedar').checked, true);
assert.equal(get('empty').hidden, true);
for (const row of get('rows').children) {
  const label = row.children[0];
  assert.equal(label.tagName, 'label');
  assert.ok(label.children.includes(findCheckbox(row)));
  assert.ok(label.textContent);
}
console.log('PASS: filter recovery restores checked states and row-label structure');

select('Amber', false);
select('Cedar', false);
assert.equal(get('count').textContent, '0 selected');
assert.equal(get('export').disabled, true);
filter('no-match');
assert.equal(get('empty').hidden, false);
assert.equal(get('export').disabled, true);
filter('');
assert.equal(get('export').disabled, true);
console.log('PASS: clearing selection disables export across empty and restored filters');
console.log('All handler checks passed. Browser, keyboard, accessible-name computation, and visual checks are unverified.');

